package vn.contractgovernance.api.notice;

import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import vn.contractgovernance.api.change.*;
import vn.contractgovernance.api.contract.*;
import vn.contractgovernance.api.customer.CustomerAccess;
import vn.contractgovernance.api.files.*;
import vn.contractgovernance.api.identity.UserDirectory;
import vn.contractgovernance.api.obligation.LifecycleObligations;
import vn.contractgovernance.api.shared.*;
import vn.contractgovernance.api.signing.SigningEvidence;
import static vn.contractgovernance.api.change.ChangeService.id;

/** Notice is immutable source plus separate assessments, never an inferred email/acknowledgement. */
@Service
public class NoticeService implements ChangeNoticeBridge {
 public record Source(UUID id,int number,JsonNode body,String hash,UUID changeRevision,UUID job) {}
 private final EntityStore store;private final JsonSupport json;private final Clock clock;private final UserDirectory users;
 private final CustomerAccess customers;private final ContractLifecycle lifecycle;private final ChangeService changes;private final ChangeApproval approval;
 private final FileService files;private final EvidenceAccess evidence;private final CommandExecutor commands;private final AuditService audit;
 private final ListQueries lists;private final ContractRegistry schemas;private final JobQueue jobs;private final AgreementRenderer renderer;private final LifecycleObligations duties;
 public NoticeService(EntityStore store,JsonSupport json,Clock clock,UserDirectory users,CustomerAccess customers,ContractLifecycle lifecycle,ChangeService changes,ChangeApproval approval,FileService files,EvidenceAccess evidence,CommandExecutor commands,AuditService audit,ListQueries lists,ContractRegistry schemas,JobQueue jobs,AgreementRenderer renderer,LifecycleObligations duties){this.store=store;this.json=json;this.clock=clock;this.users=users;this.customers=customers;this.lifecycle=lifecycle;this.changes=changes;this.approval=approval;this.files=files;this.evidence=evidence;this.commands=commands;this.audit=audit;this.lists=lists;this.schemas=schemas;this.jobs=jobs;this.renderer=renderer;this.duties=duties;}
 public String now(){return JsonSupport.timestamp(clock.instant());}
 public EntityStore.Entity require(UUID noticeId,Actor actor){var notice=store.require("Notice",noticeId);var current=users.actor(actor.id());current.requireBranch(notice.branchId());lifecycle.require(id(notice.body(),"contractId"),current);return notice;}
 public EntityStore.Entity lock(UUID noticeId){var notice=store.require("Notice",noticeId);lifecycle.lock(id(notice.body(),"contractId"));if(notice.body().hasNonNull("changeId"))store.lock("Change",id(notice.body(),"changeId"));return store.lock("Notice",noticeId);}
 public void maker(UUID noticeId,Actor actor){var n=require(noticeId,actor);makerContract(id(n.body(),"contractId"),actor);}
 private void makerContract(UUID contract,Actor actor){var c=lifecycle.require(contract,actor);customers.requireAssignedMaker(id(c.body(),"relationshipId"),users.actor(actor.id()));}
 public Set<UUID> contributors(EntityStore.Entity notice){var result=new TreeSet<>(SigningEvidence.uniqueIds(notice.body().path("contributorIds"),"/contributorIds"));store.jdbc().query("select body->>'uploadedBy' from cg_entity where entity_type='File' and body->>'targetKind'='NOTICE' and body->>'targetId'=? and body->>'uploadedBy' is not null",(rs,n)->UUID.fromString(rs.getString(1)),notice.id().toString()).forEach(result::add);return result;}
 private void checker(UUID id,Actor actor){var n=require(id,actor);users.actor(actor.id()).requireRole("CHECKER");if(contributors(n).contains(actor.id()))throw ApiException.of("SOD_VIOLATION","Cần checker độc lập với nguồn thông báo/chứng cứ.");}
 private void authorize(UUID id,String action,Actor actor){if(Set.of("APPROVE","RETURN","REJECT","RECORD_RECEIPT","VERIFY_ACK").contains(action))checker(id,actor);else maker(id,actor);}
 public EntityStore.Entity save(EntityStore.Entity n,ObjectNode b,Actor actor,String action,String reason){b.put("updatedAt",now());var next=store.update(n,b);schemas.validateSchema("Notice",next.body());audit.record(actor,action,next,reason);return next;}
 private void state(EntityStore.Entity n,String... states){if(!Set.of(states).contains(n.body().path("state").asString()))throw ApiException.of("STATE_CONFLICT","Trạng thái thông báo không cho phép thao tác.");}
 private void contribute(EntityStore.Entity n,ObjectNode body,Actor actor){var ids=contributors(n);ids.add(actor.id());if(ids.size()>50)throw ApiException.validation("/contributorIds","Vượt giới hạn người đóng góp.");body.set("contributorIds",json.value(ids.stream().map(UUID::toString).toList()));}
 public ApiResult create(JsonNode request,String key,Actor actor){var contractId=id(request,"contractId");makerContract(contractId,actor);return commands.execute(actor,key,"POST","/api/v1/notices",request,null,()->makerContract(contractId,actor),()->{
  var c=lifecycle.lock(contractId);makerContract(contractId,actor);var relationship=store.lock("Relationship",id(c.body(),"relationshipId"));
  if(request.hasNonNull("changeId")){var change=changes.lock(id(request,"changeId"));if(!change.body().path("contractId").asString().equals(contractId.toString()))throw ApiException.of("NOT_FOUND","Change không thuộc hợp đồng.");}
  var b=(ObjectNode)json.nfc(request);b.put("createdAt",now()).put("updatedAt",now()).put("branchId",c.branchId().toString()).put("state","DRAFT").put("channel","EMAIL").put("messageId",UUID.randomUUID().toString()).put("superseded",false).put("contactVersion",relationship.body().path("contactVersion").asInt());b.set("recipient",relationship.body().path("confirmedContact").deepCopy());b.set("contributorIds",json.array().add(actor.id().toString()));b.set("allowedActions",json.array());b.set("blockedActions",json.array());
  for(String f:List.of("jobId","dispatchAt","deliveredAt","deemedReceivedAt","acknowledgedAt","receiptEvidence","artifactId","artifactHash","artifactJobId","recipientSnapshotHash","ackCandidate"))b.putNull(f);
  validateTarget(b);var notice=store.create("Notice",UUID.randomUUID(),c.branchId(),b);schemas.validateSchema("Notice",notice.body());audit.record(actor,"CREATE",notice,null);return ApiResult.created(project(notice.body(),actor),"/api/v1/notices/"+notice.id());
 });}
 private void validateTarget(JsonNode body){
  if(body.path("purpose").asString().equals("TARIFF_CHANGE")){
   if(!body.hasNonNull("changeId"))throw ApiException.validation("/changeId","Thông báo phí cần Change cụ thể.");
   var ch=store.require("Change",id(body,"changeId"));
   if(!ch.body().path("contractId").equals(body.path("contractId"))||!ch.body().path("target").path("kind").asString().equals("TARIFF_NOTICE"))throw ApiException.validation("/changeId","Cần đúng tariff Change của hợp đồng.");
   if(!Set.of("APPROVED","READY").contains(ch.body().path("state").asString()))throw ApiException.of("STATE_CONFLICT","Tariff Change phải đã được duyệt.");
   if(!body.path("clauseVersion").asString().equals("TARIFF-ACK-7D-1"))throw ApiException.validation("/clauseVersion","Sai điều khoản thông báo phí.");
  }
 }
 public ApiResult update(UUID id,JsonNode request,String tag,String key,Actor actor){maker(id,actor);ETags.require(tag);return commands.execute(actor,key,"PUT","/api/v1/notices/"+id,request,tag,()->maker(id,actor),()->{var n=lock(id);maker(id,actor);ETags.check(tag,n.version());state(n,"DRAFT");var b=(ObjectNode)n.body().deepCopy();b.set("subject",json.nfc(request.path("subject")));b.set("bodyText",json.nfc(request.path("bodyText")));contribute(n,b,actor);return ApiResult.ok(project(save(n,b,actor,"UPDATE",null).body(),actor));});}
 public ApiResult command(UUID id,JsonNode request,String tag,String key,Actor actor){String action=request.path("action").asString();authorize(id,action,actor);ETags.require(tag);return commands.execute(actor,key,"POST","/api/v1/notices/"+id+"/commands",request,tag,()->authorize(id,action,actor),()->{
  var n=lock(id);authorize(id,action,actor);ETags.check(tag,n.version());var b=(ObjectNode)n.body().deepCopy();
  switch(action){
   case "SUBMIT"->{state(n,"DRAFT");validateTarget(b);var c=store.require("Contract",id(b,"contractId"));var relationship=store.lock("Relationship",id(c.body(),"relationshipId"));if(!ChangeService.counter(request.path("expectedContactVersion"),relationship.body().path("contactVersion")))throw ApiException.of("BASE_CONFLICT","Confirmed contact đã đổi.");b.set("recipient",relationship.body().path("confirmedContact").deepCopy());b.set("contactVersion",relationship.body().path("contactVersion"));b.put("recipientSnapshotHash",recipientHash(b));contribute(n,b,actor);b.put("state","IN_REVIEW");prepare(n,b,actor);}
   case "APPROVE"->{state(n,"IN_REVIEW");dependency(n);artifactFile(n,actor);event(n,"APPROVE",request,actor);b.put("state","APPROVED");}
   case "RETURN","REJECT"->{state(n,"IN_REVIEW");event(n,action,request,actor);cancelJobs(n);b.put("state",action.equals("RETURN")?"DRAFT":"CANCELLED");if(action.equals("RETURN")){for(String f:List.of("artifactId","artifactHash","artifactJobId","recipientSnapshotHash"))b.putNull(f);}}
   case "DISPATCH"->{state(n,"APPROVED");if(!b.path("transport").asString().equals("LOCAL_CAPTURE"))throw ApiException.of("STATE_CONFLICT","Nguồn external phải được ghi nhận riêng.");dispatch(n,b,actor);}
   case "RETRY"->{state(n,"FAILED");if(!b.path("transport").asString().equals("LOCAL_CAPTURE"))throw ApiException.of("STATE_CONFLICT","Không có local dispatch để retry.");retryDispatch(n,b,actor,request.path("reason").asString());}
   case "RECORD_EXTERNAL_DISPATCH"->{state(n,"APPROVED");if(!b.path("transport").asString().equals("MANUAL_EXTERNAL"))throw ApiException.of("STATE_CONFLICT","Thông báo dùng local capture.");artifactFile(n,actor);dependency(n);approvedSource(n);nonfuture(request.path("dispatchAt"));receipt(n,request.path("receiptEvidence"),actor);if(Instant.parse(request.path("receiptEvidence").path("observedAt").asString()).isBefore(Instant.parse(request.path("dispatchAt").asString())))throw ApiException.validation("/receiptEvidence/observedAt","Nguồn quan sát không được trước dispatch.");contribute(n,b,actor);b.put("state","DISPATCHED");b.set("dispatchAt",request.path("dispatchAt"));b.set("receiptEvidence",request.path("receiptEvidence"));event(n,"EXTERNAL_DISPATCH",request,actor);createDuty(n,b);}
   case "RECORD_RECEIPT"->{state(n,"DISPATCHED","ACKNOWLEDGED");dependency(n);artifactFile(n,actor);receipt(n,request.path("receiptEvidence"),actor);for(String f:List.of("deliveredAt","deemedReceivedAt")){if(request.hasNonNull(f)){nonfuture(request.path(f));if(Instant.parse(request.path(f).asString()).isBefore(Instant.parse(b.path("dispatchAt").asString())))throw ApiException.validation("/"+f,"Receipt không được trước dispatch.");}b.set(f,request.path(f));}b.set("receiptEvidence",request.path("receiptEvidence"));event(n,"RECORD_RECEIPT",request,actor);}
   case "RECORD_ACK"->{state(n,"DISPATCHED");dependency(n);artifactFile(n,actor);nonfuture(request.path("acknowledgedAt"));if(Instant.parse(request.path("acknowledgedAt").asString()).isBefore(Instant.parse(b.path("dispatchAt").asString())))throw ApiException.validation("/acknowledgedAt","ACK không được trước dispatch.");if(!request.path("artifactHash").equals(b.path("artifactHash"))||!request.path("recipientSnapshotHash").equals(b.path("recipientSnapshotHash")))throw ApiException.of("BASE_CONFLICT","ACK không khớp artifact/người nhận đã chốt.");if(b.hasNonNull("ackCandidate")&&b.path("ackCandidate").path("verificationStatus").asString().equals("PENDING"))throw ApiException.of("STATE_CONFLICT","Đang có ACK candidate chờ xác minh.");var manifest=manifest(n,SigningEvidence.uniqueIds(request.path("evidenceFileIds"),"/evidenceFileIds"),actor);contribute(n,b,actor);var candidate=(ObjectNode)request.deepCopy();candidate.remove("action");candidate.put("id",UUID.randomUUID().toString()).put("noticeId",id.toString()).put("recordedBy",actor.id().toString()).put("recordedAt",now()).put("verificationStatus","PENDING").putNull("verifiedBy").putNull("verifiedAt").putNull("verificationReason");schemas.validateSchema("AckCandidate",candidate);var source=source(n);store.jdbc().update("insert into cg_notice_ack_input(id,notice_id,source_id,input,input_hash,file_manifest,recorded_by,recorded_at) values(?,?,?,?::jsonb,?,?::jsonb,?,?)",id(candidate,"id"),id,source.id(),json.stringify(candidate),json.hash(candidate),json.stringify(manifest),actor.id(),Timestamp.from(clock.instant()));b.set("ackCandidate",candidate);}
   case "VERIFY_ACK"->{state(n,"DISPATCHED");dependency(n);artifactFile(n,actor);if(!b.hasNonNull("ackCandidate")||!b.path("ackCandidate").path("id").equals(request.path("candidateId"))||!b.path("ackCandidate").path("verificationStatus").asString().equals("PENDING"))throw ApiException.of("STATE_CONFLICT","ACK candidate không còn chờ.");verifyCandidate(n,b.path("ackCandidate"),actor);var candidate=(ObjectNode)b.path("ackCandidate").deepCopy();boolean accept=request.path("decision").asString().equals("ACCEPT");candidate.put("verificationStatus",accept?"VERIFIED":"RETURNED").put("verifiedBy",actor.id().toString()).put("verifiedAt",now()).put("verificationReason",request.path("reason").asString());var assessment=(ObjectNode)request.deepCopy();assessment.set("sourceContributors",json.value(contributors(n).stream().map(UUID::toString).toList()));store.jdbc().update("insert into cg_notice_ack_assessment(candidate_id,assessment,assessment_hash,assessed_by,assessed_at) values(?,?::jsonb,?,?,?)",id(candidate,"id"),json.stringify(assessment),json.hash(assessment),actor.id(),Timestamp.from(Instant.parse(candidate.path("verifiedAt").asString())));b.set("ackCandidate",candidate);if(accept){b.put("state","ACKNOWLEDGED");b.set("acknowledgedAt",candidate.path("acknowledgedAt"));duties.acceptNoticeAck(n,candidate,actor);}}
   case "CANCEL"->{state(n,"DRAFT","IN_REVIEW","APPROVED","QUEUED","FAILED");cancelJobs(n);b.put("state","CANCELLED");}
   default->throw ApiException.validation("/action","Thao tác không hỗ trợ.");
  }
  var updated=save(n,b,actor,action,request.hasNonNull("reason")?request.path("reason").asString():null);if(Set.of("CANCEL","REJECT").contains(action)&&b.hasNonNull("changeId"))changes.detachNotice(store.require("Change",id(b,"changeId")),n.id(),actor);
  if(Set.of("VERIFY_ACK","RECORD_RECEIPT").contains(action)&&updated.body().path("state").asString().equals("ACKNOWLEDGED"))promote(updated,actor);
  return ApiResult.ok(project(updated.body(),actor));
 });}
 private void prepare(EntityStore.Entity n,ObjectNode body,Actor actor){
  var contract=store.require("Contract",id(body,"contractId"));var source=json.object().put("noticeId",n.id().toString()).put("generatedAt",now());var frozen=(ObjectNode)body.deepCopy();for(String f:List.of("allowedActions","blockedActions","version","updatedAt","artifactId","artifactHash","artifactJobId"))frozen.remove(f);source.set("notice",frozen);source.set("manifest",renderer.manifest());var metadata=json.object();if(contract.body().hasNonNull("currentVersion"))metadata.set("contractVersion",contract.body().path("currentVersion"));else metadata.set("approvedTerms",contract.body().path("approvedTerms"));UUID revision=null;
  if(body.path("purpose").asString().equals("TARIFF_CHANGE")){var change=store.require("Change",id(body,"changeId"));var approved=approval.frozen(change);revision=id(approved.revision(),"id");metadata.set("changeRevision",approved.revision());metadata.set("changeSource",approved.metadata());changes.attachNotice(change,n.id(),actor);}
  var attachmentIds=store.jdbc().query("select id from cg_entity where entity_type='File' and body->>'targetKind'='NOTICE' and body->>'targetId'=? and body->>'origin'='UPLOADED' order by id",(rs,i)->rs.getObject(1,UUID.class),n.id().toString());source.set("attachments",manifest(n,attachmentIds,actor));source.set("metadata",metadata);var hash=json.hash(source);UUID sourceId=UUID.randomUUID();int number=store.jdbc().queryForObject("select coalesce(max(revision),0)+1 from cg_notice_source where notice_id=?",Integer.class,n.id());var job=jobs.enqueue("ARTIFACT_PDF","NOTICE",n.id(),n.branchId(),n.version()+1,hash,"ARTIFACT_PDF:NOTICE:"+sourceId,json.object().put("sourceId",sourceId.toString()),AuditService.traceId());store.jdbc().update("insert into cg_notice_source(id,notice_id,revision,source,source_hash,change_revision_id,job_id,created_at) values(?,?,?,?::jsonb,?,?,?,?)",sourceId,n.id(),number,json.stringify(source),hash,revision,job,Timestamp.from(clock.instant()));body.put("artifactJobId",job.toString());
 }
 public Source source(EntityStore.Entity n){if(!n.body().hasNonNull("artifactJobId"))throw ApiException.of("ARTIFACT_NOT_READY","Chưa có submitted source.");return store.jdbc().query("select id,revision,source::text,source_hash,change_revision_id,job_id from cg_notice_source where notice_id=? and job_id=?",(rs,i)->new Source(rs.getObject(1,UUID.class),rs.getInt(2),json.parse(rs.getString(3)),rs.getString(4),rs.getObject(5,UUID.class),rs.getObject(6,UUID.class)),n.id(),id(n.body(),"artifactJobId")).stream().findFirst().orElseThrow(()->ApiException.of("STORAGE_INTEGRITY","Thiếu nguồn Notice bất biến."));}
 public void sourceIntegrity(EntityStore.Entity n,Source source){var ids=new TreeSet<UUID>();for(var file:source.body().path("attachments"))ids.add(id(file,"fileId"));if(!manifest(n,ids,null,false).equals(source.body().path("attachments")))throw ApiException.of("STORAGE_INTEGRITY","Approved Notice attachment manifest differs.");if(!source.hash().equals(json.hash(source.body())))throw ApiException.of("STORAGE_INTEGRITY","Notice source hash sai.");for(String f:List.of("contractId","changeId","purpose","clauseVersion","subject","bodyText","recipient","contactVersion","channel","transport","messageId","recipientSnapshotHash"))if(!n.body().path(f).equals(source.body().path("notice").path(f)))throw ApiException.of("STORAGE_INTEGRITY","Notice khác nguồn đã nộp.");}
 public void artifactFile(EntityStore.Entity n,Actor actor){var s=source(n);sourceIntegrity(n,s);if(!n.body().hasNonNull("artifactId"))throw ApiException.of("ARTIFACT_NOT_READY","PDF Notice chưa sẵn sàng.");if(store.jdbc().queryForObject("select count(*) from cg_notice_artifact where source_id=? and file_id=? and source_hash=? and artifact_hash=?",Long.class,s.id(),id(n.body(),"artifactId"),s.hash(),n.body().path("artifactHash").asString())!=1L)throw ApiException.of("STORAGE_INTEGRITY","Artifact binding sai.");manifest(n,List.of(id(n.body(),"artifactId")),actor,false);}
 public JsonNode manifest(EntityStore.Entity n,Collection<UUID> ids,Actor actor){return manifest(n,ids,actor,true);}
 public JsonNode manifest(EntityStore.Entity n,Collection<UUID> ids,Actor actor,boolean attach){var result=json.array();var rows=new ArrayList<JsonNode>();for(var fileId:new TreeSet<>(ids)){var file=attach?store.lock("File",fileId):store.require("File",fileId);if(!file.body().path("targetKind").asString().equals("NOTICE")||!file.body().path("targetId").asString().equals(n.id().toString())||!Objects.equals(file.branchId(),n.branchId()))throw ApiException.of("NOT_FOUND","Evidence không thuộc đúng Notice.");if(!file.body().path("state").asString().equals("CLEAN"))throw ApiException.of("FILE_NOT_CLEAN","Evidence chưa CLEAN.");if(actor!=null){evidence.requireFile(fileId,actor);evidence.requireFull(file,users.actor(actor.id()));}var hash=file.body().path("sha256").asString();if(!hash.equals(files.blob(fileId).hash()))throw ApiException.of("STORAGE_INTEGRITY","Hash metadata sai.");files.bytesForScan(fileId,hash);rows.add(json.object().put("fileId",fileId.toString()).put("purpose",file.body().path("purpose").asString()).put("sha256",hash));if(attach&&!file.body().path("attached").asBoolean()){var attached=(ObjectNode)file.body().deepCopy();attached.put("attached",true).put("updatedAt",now());store.update(file,attached);}if(attach)store.jdbc().update("insert into cg_file_association(file_id,target_type,target_id,historical,created_at) values(?,'NOTICE',?,true,?) on conflict(file_id,target_type,target_id) do update set historical=true",fileId,n.id(),Timestamp.from(clock.instant()));}rows.sort(Comparator.comparing((JsonNode r)->r.path("purpose").asString()).thenComparing(r->r.path("fileId").asString()));rows.forEach(result::add);return result;}
 public void nonfuture(JsonNode value){if(Instant.parse(value.asString()).isAfter(clock.instant()))throw ApiException.validation("/timestamp","Thời điểm chứng cứ không được ở tương lai.");}
 private String recipientHash(JsonNode body){var value=json.object();value.set("recipient",body.path("recipient"));value.set("contactVersion",body.path("contactVersion"));return json.hash(value);}
 private void receipt(EntityStore.Entity n,JsonNode input,Actor actor){nonfuture(input.path("observedAt"));manifest(n,SigningEvidence.uniqueIds(input.path("fileIds"),"/receiptEvidence/fileIds"),actor);}
 public void event(EntityStore.Entity n,String kind,JsonNode input,Actor actor){if(input.hasNonNull("receiptEvidence")){var bound=(ObjectNode)input.deepCopy();if(kind.equals("RECORD_RECEIPT"))bound.set("sourceContributors",json.value(contributors(n).stream().map(UUID::toString).toList()));bound.set("fileManifest",manifest(n,SigningEvidence.uniqueIds(input.path("receiptEvidence").path("fileIds"),"/receiptEvidence/fileIds"),actor));input=bound;}UUID source=n.body().hasNonNull("artifactJobId")?source(n).id():null;store.jdbc().update("insert into cg_notice_event(id,notice_id,source_id,kind,body,body_hash,actor_id,recorded_at) values(?,?,?, ?,?::jsonb,?,?,?)",UUID.randomUUID(),n.id(),source,kind,json.stringify(input),json.hash(input),actor==null?null:actor.id(),Timestamp.from(clock.instant()));}
 public void dependency(EntityStore.Entity n){if(n.body().path("superseded").asBoolean()||n.body().path("state").asString().equals("CANCELLED"))throw ApiException.of("STATE_CONFLICT","Notice đã hủy/superseded.");if(n.body().hasNonNull("changeId")){var ch=store.require("Change",id(n.body(),"changeId"));if(Set.of("CANCELLED","REJECTED","CONFLICTED","APPLIED").contains(ch.body().path("state").asString()))throw ApiException.of("STATE_CONFLICT","Change không còn dùng Notice.");if(n.body().path("purpose").asString().equals("TARIFF_CHANGE")&&(!ch.body().path("noticeId").asString().equals(n.id().toString())||!approval.frozen(ch).revision().path("id").asString().equals(Objects.toString(source(n).changeRevision(),""))))throw ApiException.of("BASE_CONFLICT","Notice không còn liên kết revision hiện hành.");}}
 public void dispatch(EntityStore.Entity n,ObjectNode b,Actor actor){dependency(n);artifactFile(n,actor);approvedSource(n);var source=source(n);if(store.jdbc().queryForObject("select count(*) from cg_notice_event where notice_id=? and source_id=? and kind='APPROVE'",Long.class,n.id(),source.id())!=1L)throw ApiException.of("NOTICE_NOT_READY","Thiếu independent approval.");var payload=json.object().put("sourceId",source.id().toString()).put("sourceHash",source.hash()).put("messageId",b.path("messageId").asString()).put("artifactHash",b.path("artifactHash").asString());var job=jobs.enqueue("NOTICE_DISPATCH","NOTICE",n.id(),n.branchId(),n.version()+1,json.hash(payload),"NOTICE_DISPATCH:"+source.id(),payload,AuditService.traceId());b.put("state","QUEUED").put("jobId",job.toString());}
 public void approvedSource(EntityStore.Entity n){if(store.jdbc().queryForObject("select count(*) from cg_notice_event where notice_id=? and source_id=? and kind='APPROVE'",Long.class,n.id(),source(n).id())!=1L)throw ApiException.of("NOTICE_NOT_READY","Thiếu independent exact source approval.");}
 private void retryDispatch(EntityStore.Entity n,ObjectNode b,Actor actor,String reason){var job=store.lock("Job",id(b,"jobId"));requireDispatchRetry(job,actor);if(!jobs.retry(job.id()))throw ApiException.of("STATE_CONFLICT","Job đã đổi.");b.put("state","QUEUED");audit.record(actor,"RETRY",store.require("Job",job.id()),reason);}
 public void cancelJobs(EntityStore.Entity n){store.jdbc().update("update cg_job set state='CANCELLED',lease_owner=null,lease_until=null,error_code='GUARD_BLOCKED',updated_at=? where target_type='NOTICE' and target_id=? and state in ('QUEUED','RUNNING','FAILED')",Timestamp.from(clock.instant()),n.id());}
 public void createDuty(EntityStore.Entity n,JsonNode body){if(body.path("purpose").asString().equals("TARIFF_CHANGE"))duties.noticeAck(store.require("Contract",id(body,"contractId")),n.id(),source(n).number(),store.require("Change",id(body,"changeId")).body().path("effectiveOn").asString(),Instant.parse(body.path("dispatchAt").asString()),body.path("contributorIds"));}
 private void verifyCandidate(EntityStore.Entity n,JsonNode candidate,Actor actor){verifyCandidate(n,candidate,actor,actor.id());}
 private void verifyCandidate(EntityStore.Entity n,JsonNode candidate,Actor actor,UUID assessor){var source=source(n);var rows=store.jdbc().query("select input::text,input_hash,file_manifest::text,recorded_by from cg_notice_ack_input where id=? and notice_id=? and source_id=?",(rs,i)->List.of(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4)),id(candidate,"id"),n.id(),source.id());if(rows.size()!=1||rows.getFirst().get(3).equals(assessor.toString()))throw ApiException.of("SOD_VIOLATION","ACK cần người xác minh khác recorder.");var input=json.parse(rows.getFirst().get(0));if(!json.hash(input).equals(rows.getFirst().get(1)))throw ApiException.of("STORAGE_INTEGRITY","ACK source hash sai.");for(String f:List.of("id","noticeId","artifactHash","recipientSnapshotHash","acknowledgedAt","evidenceFileIds","basis","recordedBy","recordedAt"))if(!candidate.path(f).equals(input.path(f)))throw ApiException.of("STORAGE_INTEGRITY","ACK khác source.");if(!candidate.path("artifactHash").equals(n.body().path("artifactHash"))||!candidate.path("recipientSnapshotHash").equals(n.body().path("recipientSnapshotHash"))||!manifest(n,SigningEvidence.uniqueIds(candidate.path("evidenceFileIds"),"/evidenceFileIds"),actor,false).equals(json.parse(rows.getFirst().get(2))))throw ApiException.of("STORAGE_INTEGRITY","ACK evidence/hash đã đổi.");}
 private void promote(EntityStore.Entity n,Actor actor){if(!n.body().path("purpose").asString().equals("TARIFF_CHANGE"))return;var ch=store.require("Change",id(n.body(),"changeId"));if(!ch.body().path("state").asString().equals("APPROVED"))return;try{requireReady(ch,actor);changes.promoteNotice(ch,n.id(),actor);}catch(ApiException blocker){event(n,"TARIFF_NOT_READY",json.object().put("code",blocker.code()),actor);}}
 @Override public void requireReady(EntityStore.Entity change,Actor actor){if(!change.body().hasNonNull("noticeId"))throw ApiException.of("NOTICE_NOT_READY","Thiếu Notice.");var n=store.require("Notice",id(change.body(),"noticeId"));dependency(n);artifactFile(n,actor);if(!n.body().path("state").asString().equals("ACKNOWLEDGED")||!n.body().path("purpose").asString().equals("TARIFF_CHANGE")||!n.body().path("changeId").asString().equals(change.id().toString()))throw ApiException.of("NOTICE_NOT_READY","Thiếu verified ACK đúng Notice.");var candidate=n.body().path("ackCandidate");if(!candidate.path("verificationStatus").asString().equals("VERIFIED"))throw ApiException.of("NOTICE_NOT_READY","ACK chưa xác minh.");var reviewer=id(candidate,"verifiedBy");verifyCandidate(n,candidate,null,reviewer);var assessments=store.jdbc().query("select assessment::text,assessment_hash,assessed_by,assessed_at from cg_notice_ack_assessment where candidate_id=?",(rs,i)->List.of(rs.getString(1),rs.getString(2),rs.getObject(3,UUID.class).toString(),JsonSupport.timestamp(rs.getTimestamp(4).toInstant())),id(candidate,"id"));if(assessments.size()!=1)throw ApiException.of("NOTICE_NOT_READY","Thiếu ACK assessment.");var recorded=assessments.getFirst();var assessed=json.parse(recorded.get(0));if(!json.hash(assessed).equals(recorded.get(1))||!reviewer.toString().equals(recorded.get(2))||!candidate.path("verifiedAt").asString().equals(recorded.get(3))||!assessed.path("decision").asString().equals("ACCEPT")||!assessed.path("candidateId").equals(candidate.path("id"))||!assessed.path("reason").equals(candidate.path("verificationReason"))||SigningEvidence.uniqueIds(assessed.path("sourceContributors"),"/sourceContributors").contains(reviewer))throw ApiException.of("STORAGE_INTEGRITY","ACK assessment/source binding hoặc historical independence sai.");
  if(n.body().path("transport").asString().equals("LOCAL_CAPTURE")){var rows=captureRows(n);if(rows.size()!=1||!rows.getFirst().path("artifactHash").equals(n.body().path("artifactHash"))||!rows.getFirst().path("acceptedAt").equals(n.body().path("dispatchAt")))throw ApiException.of("NOTICE_NOT_READY","Thiếu authoritative local capture.");}else requireReceipt(n);
  var earliest=Instant.parse(n.body().path("dispatchAt").asString()).atZone(CalendarService.ZONE).toLocalDate().plusDays(7);var ack=Instant.parse(n.body().path("acknowledgedAt").asString()).atZone(CalendarService.ZONE).toLocalDate().plusDays(1);if(ack.isAfter(earliest))earliest=ack;if(LocalDate.parse(change.body().path("effectiveOn").asString()).isBefore(earliest))throw ApiException.of("NOTICE_LEAD_TOO_SHORT","Chưa đủ 7 ngày lịch từ dispatch và ACK+1.");changes.recheckNotice(change,actor);
 }
 @Override public JsonNode artifact(EntityStore.Entity change){var n=store.require("Notice",id(change.body(),"noticeId"));artifactFile(n,null);var result=json.object();result.set("artifactId",n.body().path("artifactId"));result.set("artifactHash",n.body().path("artifactHash"));return result;}
 @Override public void cleanup(EntityStore.Entity change,String reason,Actor actor){var notices=store.jdbc().query("select id from cg_entity where entity_type='Notice' and body->>'changeId'=? order by id",(rs,i)->rs.getObject(1,UUID.class),change.id().toString());for(var id:notices){var n=store.lock("Notice",id);var b=(ObjectNode)n.body().deepCopy();if(Set.of("DISPATCHED","ACKNOWLEDGED").contains(b.path("state").asString()))b.put("superseded",true);else if(!b.path("state").asString().equals("CANCELLED")){cancelJobs(n);b.put("state","CANCELLED");}save(n,b,actor,"SUPERSEDE",reason);duties.supersedeNoticeAck(n,reason,actor);}}
 public JsonNode controlProof(UUID noticeId,UUID contractId,Actor actor,boolean termination){var n=actor==null?store.require("Notice",noticeId):require(noticeId,actor);if(!n.body().path("contractId").asString().equals(contractId.toString())||(termination&&!n.body().path("purpose").asString().equals("TERMINATION"))||n.body().path("superseded").asBoolean()||!Set.of("DISPATCHED","ACKNOWLEDGED").contains(n.body().path("state").asString()))throw ApiException.of("NOTICE_NOT_READY","Termination notice source chưa dispatched hoặc sai mục đích.");artifactFile(n,actor);approvedSource(n);if(n.body().path("transport").asString().equals("LOCAL_CAPTURE")){if(captureRows(n).size()!=1)throw ApiException.of("NOTICE_NOT_READY","Thiếu local capture provenance.");}else requireReceipt(n);var proof=json.object().put("noticeId",n.id().toString()).put("sourceId",source(n).id().toString()).put("sourceHash",source(n).hash());for(String field:List.of("artifactId","artifactHash","recipientSnapshotHash","dispatchAt","transport"))proof.set(field,n.body().path(field));return proof;}
 public void endApplicability(UUID contract,Actor actor){var ids=store.jdbc().query("select id from cg_entity where entity_type='Notice' and body->>'contractId'=? and body->>'purpose'='TARIFF_CHANGE' order by id",(rs,n)->rs.getObject(1,UUID.class),contract.toString());for(var id:ids){var n=store.lock("Notice",id);var b=(ObjectNode)n.body().deepCopy();if(Set.of("DISPATCHED","ACKNOWLEDGED").contains(b.path("state").asString()))b.put("superseded",true);else{cancelJobs(n);b.put("state","CANCELLED");}save(n,b,actor,"SUPERSEDE","Contract terminated; tariff change no longer applies");duties.supersedeNoticeAck(n,"Contract terminated",actor);}}
 public void authorizeRetry(UUID noticeId,Actor actor){maker(noticeId,actor);}
 public void requireDispatchRetry(EntityStore.Entity job,Actor actor){var n=require(id(job.body(),"parentId"),actor);maker(n.id(),actor);state(n,"FAILED");dependency(n);artifactFile(n,actor);if(!job.body().path("state").asString().equals("FAILED")||!n.body().path("jobId").asString().equals(job.id().toString()))throw ApiException.of("STATE_CONFLICT","Dispatch job không còn hiện hành.");requireDispatchSource(n,job.id());}
 public void requireDispatchSource(EntityStore.Entity n,UUID jobId){approvedSource(n);var source=source(n);var rows=store.jdbc().query("select payload::text,expected_hash from cg_job where id=? and kind='NOTICE_DISPATCH' and target_type='NOTICE' and target_id=?",(rs,i)->List.of(rs.getString(1),rs.getString(2)),jobId,n.id());if(rows.size()!=1)throw ApiException.of("STORAGE_INTEGRITY","Thiếu dispatch job đúng Notice.");var payload=json.parse(rows.getFirst().get(0));if(!json.hash(payload).equals(rows.getFirst().get(1))||!payload.path("sourceId").asString().equals(source.id().toString())||!payload.path("sourceHash").asString().equals(source.hash())||!payload.path("messageId").equals(n.body().path("messageId"))||!payload.path("artifactHash").equals(n.body().path("artifactHash")))throw ApiException.of("STORAGE_INTEGRITY","Dispatch intent differs from approved Notice.");}
 public EntityStore.Entity retryJob(UUID jobId,String tag,String reason,Actor actor){var preview=store.require("Job",jobId);var n=lock(id(preview.body(),"parentId"));var job=store.lock("Job",jobId);ETags.check(tag,job.version());var b=(ObjectNode)n.body().deepCopy();retryDispatch(n,b,actor,reason);save(n,b,actor,"RETRY",reason);return store.require("Job",jobId);}
 private void requireReceipt(EntityStore.Entity n){var rows=store.jdbc().query("select body::text,body_hash,actor_id from cg_notice_event where notice_id=? and source_id=? and kind='RECORD_RECEIPT' order by recorded_at desc,id desc limit 1",(rs,i)->List.of(rs.getString(1),rs.getString(2),rs.getObject(3,UUID.class).toString()),n.id(),source(n).id());if(rows.size()!=1)throw ApiException.of("NOTICE_NOT_READY","External dispatch chưa có independent receipt.");var row=rows.getFirst();var input=json.parse(row.get(0));if(!json.hash(input).equals(row.get(1))||SigningEvidence.uniqueIds(input.path("sourceContributors"),"/sourceContributors").contains(UUID.fromString(row.get(2))))throw ApiException.of("STORAGE_INTEGRITY","Receipt assessment không độc lập hoặc source hash sai.");if(!input.path("receiptEvidence").equals(n.body().path("receiptEvidence"))||!manifest(n,SigningEvidence.uniqueIds(input.path("receiptEvidence").path("fileIds"),"/receiptEvidence/fileIds"),null,false).equals(input.path("fileManifest")))throw ApiException.of("STORAGE_INTEGRITY","Receipt evidence đã đổi.");}
 private List<JsonNode> captureRows(EntityStore.Entity n){var rows=store.jdbc().query("select envelope::text,content_hash from cg_mailbox_capture where notice_id=? and message_id=?",(rs,i)->List.of(rs.getString(1),rs.getString(2)),n.id(),UUID.fromString(n.body().path("messageId").asString()));var result=new ArrayList<JsonNode>();for(var row:rows){var body=json.parse(row.get(0));if(!json.hash(body).equals(row.get(1)))throw ApiException.of("STORAGE_INTEGRITY","Local capture hash mismatch.");for(String f:List.of("messageId","recipient","subject","bodyText","artifactHash"))if(!body.path(f).equals(n.body().path(f)))throw ApiException.of("STORAGE_INTEGRITY","Local capture khác approved Notice.");if(!body.path("noticeId").asString().equals(n.id().toString()))throw ApiException.of("STORAGE_INTEGRITY","Local capture sai Notice.");result.add(body);}return result;}

 public JsonNode capture(UUID id,Actor actor){var n=require(id,actor);var rows=captureRows(n);if(rows.isEmpty())throw ApiException.of("NOT_FOUND","Chưa có local capture.");var result=(ObjectNode)rows.getFirst().deepCopy();if(redacted(actor)){result.set("recipient",redactContact(result.path("recipient")));result.put("subject","[REDACTED]").put("bodyText","[REDACTED]");}schemas.validateSchema("NoticeCapture",result);return result;}
 public JsonNode get(UUID id,Actor actor){return project(require(id,actor).body(),users.actor(actor.id()));}
 public JsonNode list(Map<String,String> query,Actor actor){actor=users.actor(actor.id());actor.requireRole("MAKER","CHECKER","MANAGER","DATA_OFFICER","AUDITOR");var args=new ArrayList<Object>();String where="exists(select 1 from cg_entity c join cg_entity r on r.entity_type='Relationship' and r.id=(c.body->>'relationshipId')::uuid and r.branch_id=c.branch_id where c.entity_type='Contract' and c.id=(e.body->>'contractId')::uuid and c.branch_id=e.branch_id and "+customers.businessSqlScope(actor,"r")+")";if(!actor.hasAnyRole("CHECKER","MANAGER","DATA_OFFICER","AUDITOR"))args.add(actor.id().toString());var current=actor;return lists.page("Notice",actor,query,false,where,args,b->project(b,current));}
 private boolean redacted(Actor actor){return actor.hasRole("AUDITOR")&&!actor.hasAnyRole("MAKER","CHECKER","MANAGER","DATA_OFFICER")&&!actor.hasPermission("SENSITIVE_READ");}
 private JsonNode redactContact(JsonNode raw){var c=(ObjectNode)raw.deepCopy();c.put("personName","[REDACTED]").put("roleLabel","[REDACTED]").put("email","redacted@example.invalid").put("phone","0000000000");return c;}
 public JsonNode project(JsonNode raw,Actor actor){var b=(ObjectNode)raw.deepCopy();var allowed=json.array();var blocked=json.array();String state=b.path("state").asString();for(String action:List.of("UPDATE","SUBMIT","APPROVE","RETURN","REJECT","DISPATCH","RETRY","RECORD_EXTERNAL_DISPATCH","RECORD_RECEIPT","RECORD_ACK","VERIFY_ACK","CANCEL")){boolean relevant=switch(action){case "UPDATE","SUBMIT"->state.equals("DRAFT");case "APPROVE","RETURN","REJECT"->state.equals("IN_REVIEW");case "DISPATCH"->state.equals("APPROVED")&&b.path("transport").asString().equals("LOCAL_CAPTURE");case "RECORD_EXTERNAL_DISPATCH"->state.equals("APPROVED")&&b.path("transport").asString().equals("MANUAL_EXTERNAL");case "RETRY"->state.equals("FAILED");case "RECORD_ACK"->state.equals("DISPATCHED")&&(!b.hasNonNull("ackCandidate")||b.path("ackCandidate").path("verificationStatus").asString().equals("RETURNED"));case "VERIFY_ACK"->state.equals("DISPATCHED")&&b.hasNonNull("ackCandidate")&&b.path("ackCandidate").path("verificationStatus").asString().equals("PENDING");case "RECORD_RECEIPT"->Set.of("DISPATCHED","ACKNOWLEDGED").contains(state);default->Set.of("DRAFT","IN_REVIEW","APPROVED","QUEUED","FAILED").contains(state);};if(!relevant)continue;boolean review=Set.of("APPROVE","RETURN","REJECT","RECORD_RECEIPT","VERIFY_ACK").contains(action);if(review&&!actor.hasRole("CHECKER")||!review&&!actor.hasRole("MAKER"))continue;try{authorize(id(b,"id"),action,actor);var current=store.require("Notice",id(b,"id"));if(Set.of("APPROVE","DISPATCH","RETRY","RECORD_EXTERNAL_DISPATCH","RECORD_RECEIPT","RECORD_ACK","VERIFY_ACK").contains(action)){dependency(current);artifactFile(current,actor);}if(Set.of("DISPATCH","RECORD_EXTERNAL_DISPATCH").contains(action))approvedSource(current);if(action.equals("RETRY"))requireDispatchRetry(store.require("Job",id(b,"jobId")),actor);if(action.equals("VERIFY_ACK"))verifyCandidate(current,b.path("ackCandidate"),actor);if(b.path("superseded").asBoolean())throw ApiException.of("STATE_CONFLICT","Nguồn superseded.");allowed.add(action);}catch(ApiException e){blocked.add(json.object().put("action",action).put("code",e.code()).put("reason",e.getMessage()));}}
  if(redacted(actor)){b.set("recipient",redactContact(b.path("recipient")));b.put("subject","[REDACTED]").put("bodyText","[REDACTED]");if(b.hasNonNull("receiptEvidence"))((ObjectNode)b.path("receiptEvidence")).put("basis","[REDACTED]");if(b.hasNonNull("ackCandidate")){((ObjectNode)b.path("ackCandidate")).put("basis","[REDACTED]");if(b.path("ackCandidate").hasNonNull("verificationReason"))((ObjectNode)b.path("ackCandidate")).put("verificationReason","[REDACTED]");}}
  b.set("allowedActions",allowed);b.set("blockedActions",blocked);return b;
 }
}
